punif(130, min = 120, max = 140) #Computes Pr(x <= 130) for a random variable that follows a uniform probability distribution with minimum value 120 and maximum value 140
punif(135, min = 120, max = 140) - punif(130, min = 120, max = 140) #Computes Pr(130 <= x <= 135) for a random variable that follows a uniform probability distribution with minimum value 120 and maximum value 140
qunif(0.8, min = 120, max = 140) #Computes the x value for a cumulative probability of 0.8 for a random variable that follows a uniform probability distribution with minimum value 120 and maximum value 140
pnorm(40000, 36500, 5000) #Computes Pr(x <= 40,000) for a random variable that follows normal probability distribution with mean of 36,500 and standard deviation of 5,000
qnorm(0.1, 36500, 5000) #Computes the x value for a cumulative probability of 0.1 for a random variable that follows normal probability distribution with mean of 36,500 and standard deviation of 5,000
pexp(18, 1/15) - pexp(6, 1/15) #Computes Pr(6 <= x <= 18) for a random variable that follows an exponential distribution with a mean of 15